Action.Str:
/* Load or atomically save independent speech preferences. */
voicePreferenceValue(name) {
    value = tasker.getVariable(name);
    return value == null || value.startsWith("%") ? "" : value;
}
voicePreferenceValid(value) { return "0".equals(value) || "1".equals(value); }
prefs = context.getSharedPreferences("heysig3-voice", 0);
mode = voicePreferenceValue("sig3_voice_pref_mode");
if ("save".equals(mode)) {
    responses = voicePreferenceValue("sig3_voice_results_choice");
    prompts = voicePreferenceValue("sig3_voice_prompts_choice");
    if (!voicePreferenceValid(responses) || !voicePreferenceValid(prompts))
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Invalid voice preference selection");
    if (!prefs.edit().putString("responses", responses).putString("prompts", prompts).commit())
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Voice preferences could not be saved");
} else if ("load".equals(mode)) {
    responses = voicePreferenceValue("SIG3_VoiceResponses");
    if (!voicePreferenceValid(responses)) responses = prefs.getString("responses", "1");
    if (!voicePreferenceValid(responses)) responses = "1";
    prompts = voicePreferenceValue("SIG3_VoicePrompts");
    if (!voicePreferenceValid(prompts)) prompts = prefs.getString("prompts", responses);
    if (!voicePreferenceValid(prompts)) prompts = responses;
} else throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Unknown voice preference operation");
tasker.setVariable("SIG3_VoiceResponses", responses);
tasker.setVariable("SIG3_VoicePrompts", prompts);
tasker.setVariable("SIG3_VoiceSettingsStatus", "Spoken results " + ("1".equals(responses) ? "on" : "off") + "; voice prompts " + ("1".equals(prompts) ? "on" : "off"));
return "voice preferences " + mode;

/* Prepare the readiness cue before opening microphone capture. */
import android.content.pm.PackageManager;
import android.app.NotificationManager;
import android.media.AudioManager;
readyValue(name) {
    value = tasker.getVariable(name);
    return value == null || value.startsWith("%") ? "" : value;
}
tasker.setVariable("sig3_ready_speech", "");
tasker.setVariable("SIG3_VoiceReady", "0");
tasker.setVariable("SIG3_VoiceCaptureAllowed", "0");
status = "";
pm = context.getSystemService("power"); km = context.getSystemService("keyguard");
if (!pm.isInteractive() || km.isKeyguardLocked()) status = "Turn on and unlock the phone to speak a command";
else if (context.checkSelfPermission("android.permission.RECORD_AUDIO") != PackageManager.PERMISSION_GRANTED) status = "Allow Tasker microphone access to speak a command";
else if (readyValue("TRUN").matches("(?s).*(?:^|,)SIG3_Worker(?:,|$).*")) status = "Wait for the current command to finish";
if (status.length() > 0) {
    tasker.setVariable("SIG3_VoiceStatus", status); tasker.showToast(status);
    if (status.equals("Turn on and unlock the phone to speak a command")) {
        audio = context.getSystemService("audio"); notification = context.getSystemService("notification");
        preference = readyValue("SIG3_VoicePrompts");
        if (preference.length() == 0) preference = readyValue("SIG3_VoiceResponses");
        if (!"0".equals(preference)
            && notification.getCurrentInterruptionFilter() == NotificationManager.INTERRUPTION_FILTER_ALL
            && !audio.isStreamMute(AudioManager.STREAM_MUSIC)
            && audio.getStreamVolume(AudioManager.STREAM_MUSIC) > 0
            && audio.getMode() == AudioManager.MODE_NORMAL)
            tasker.setVariable("sig3_ready_speech", "Unlock the phone, then say Hey Sig again.");
    }
    return "capture blocked";
}
tasker.setVariable("SIG3_VoiceCaptureAllowed", "1");
tasker.setVariable("SIG3_VoiceStatus", "Opening command prompt");
tasker.showToast("Sig here");
am = context.getSystemService("audio"); nm = context.getSystemService("notification");
prompts = readyValue("SIG3_VoicePrompts");
if (prompts.length() == 0) prompts = readyValue("SIG3_VoiceResponses");
// AutoVoice Media suppression can release mute after its stop action returns.
// Wait only for an enabled wake handoff; never change the user's volume.
if (!"0".equals(prompts) && "1".equals(readyValue("SIG3_WakeEnabled"))
    && nm.getCurrentInterruptionFilter() == NotificationManager.INTERRUPTION_FILTER_ALL
    && am.getMode() == AudioManager.MODE_NORMAL) {
    for (settle = 0; settle < 20; settle++) {
        if (!am.isStreamMute(AudioManager.STREAM_MUSIC)
            && am.getStreamVolume(AudioManager.STREAM_MUSIC) > 0) break;
        Thread.sleep(100);
    }
}
if (!"0".equals(prompts) && nm.getCurrentInterruptionFilter() == NotificationManager.INTERRUPTION_FILTER_ALL && !am.isStreamMute(AudioManager.STREAM_MUSIC) && am.getStreamVolume(AudioManager.STREAM_MUSIC) > 0 && am.getMode() == AudioManager.MODE_NORMAL)
    tasker.setVariable("sig3_ready_speech", "Sig here");
return "cue prepared";

/* Load or atomically save independent speech preferences. */
voicePreferenceValue(name) {
    value = tasker.getVariable(name);
    return value == null || value.startsWith("%") ? "" : value;
}
voicePreferenceValid(value) { return "0".equals(value) || "1".equals(value); }
prefs = context.getSharedPreferences("heysig3-voice", 0);
mode = voicePreferenceValue("sig3_voice_pref_mode");
if ("save".equals(mode)) {
    responses = voicePreferenceValue("sig3_voice_results_choice");
    prompts = voicePreferenceValue("sig3_voice_prompts_choice");
    if (!voicePreferenceValid(responses) || !voicePreferenceValid(prompts))
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Invalid voice preference selection");
    if (!prefs.edit().putString("responses", responses).putString("prompts", prompts).commit())
        throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Voice preferences could not be saved");
} else if ("load".equals(mode)) {
    responses = voicePreferenceValue("SIG3_VoiceResponses");
    if (!voicePreferenceValid(responses)) responses = prefs.getString("responses", "1");
    if (!voicePreferenceValid(responses)) responses = "1";
    prompts = voicePreferenceValue("SIG3_VoicePrompts");
    if (!voicePreferenceValid(prompts)) prompts = prefs.getString("prompts", responses);
    if (!voicePreferenceValid(prompts)) prompts = responses;
} else throw new com.joaomgcd.taskerm.action.java.JavaCodeException("Unknown voice preference operation");
tasker.setVariable("SIG3_VoiceResponses", responses);
tasker.setVariable("SIG3_VoicePrompts", prompts);
tasker.setVariable("SIG3_VoiceSettingsStatus", "Spoken results " + ("1".equals(responses) ? "on" : "off") + "; voice prompts " + ("1".equals(prompts) ? "on" : "off"));
return "voice preferences " + mode;

/* Speak only a fresh completed voice result, using actual app readback. */
voiceValue(name) {
    value = tasker.getVariable(name);
    return value == null || value.startsWith("%") ? "" : value;
}
tasker.setVariable("sig3_speech", "");
tasker.setVariable("SIG3_VoiceReply", "");
retry = "retry".equals(voiceValue("sig3_reply_kind"));
preference = voiceValue(retry ? "SIG3_VoicePrompts" : "SIG3_VoiceResponses");
if (retry && preference.length() == 0) preference = voiceValue("SIG3_VoiceResponses");
if ("0".equals(preference)) return "disabled";
running = voiceValue("TRUN");
if (running.matches("(?s).*(?:^|,)SIG3_Worker(?:,|$).*")) return "worker-busy";
if ("retry".equals(voiceValue("sig3_reply_kind"))) {
    reply = "Command not recognized. Tap Try again to speak again, or Cancel.";
} else {
    operation = voiceValue("SIG3_OperationId");
    if (operation.length() == 0 || operation.equals(voiceValue("sig3_reply_before"))) {
        reply = "Command was not accepted. Please try again when the current command finishes.";
    } else if (!"1".equals(voiceValue("SIG3_CommandOK"))) {
        error = voiceValue("SIG3_Error");
        reply = error.length() == 0 ? "Command did not complete. Check the phone screen." : "Command stopped. " + error;
        if (error.startsWith("Turn off Do Not Disturb")) reply = "Turn off Do Not Disturb.";
        if (error.startsWith("Raise phone ")) {
            end = error.indexOf(" volume");
            if (end > 12) {
                stream = error.substring(12, end);
                reply = "Raise phone " + stream + " volume" + (error.contains("(50% minimum)") ? " to halfway." : ".");
            }
        }
    } else if (!"complete".equals(voiceValue("SIG3_MoveStage"))) {
        reply = "Command result could not be verified. Check the phone screen.";
    } else {
        family = voiceValue("SIG3_Family");
        observed = voiceValue("SIG3_Observed");
        program = voiceValue("SIG3_Program");
        reply = "Command completed. Check the phone screen.";
        if ("Program".equals(family) && program.length() > 0) reply = "Program is " + program + ".";
        if ("Volume".equals(family) || "Balance".equals(family) || "Tinnitus".equals(family)) {
            if (observed.matches("-?[0-9]+")) {
                spoken = observed.startsWith("-") ? "minus " + observed.substring(1) : observed;
                reply = family + " is " + spoken + ".";
            }
        }
        if ("Battery".equals(family)) reply = "Battery checks requested. Listen for the hearing aid indications.";
        if (("Noise".equals(family) || "Setup".equals(family) || "Sleep".equals(family) || "Settings".equals(family)) && observed.length() > 0)
            reply = observed + ".";
        if (voiceValue("SIG3_SettingsAutoError").length() > 0) reply += " Settings were not saved. " + voiceValue("SIG3_SettingsAutoError");
    }
}
tasker.setVariable("SIG3_VoiceReply", reply);
tasker.setVariable("sig3_speech", reply);
return "ready";

